"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { Card, CardAction, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { DotPlot } from "@/registry/dashboardcn/ui/dot-plot"

export interface DotPlotCardProps extends Omit<React.ComponentProps<typeof Card>, "children"> {
  title: string
  /** Headline value. Numbers are formatted with `format`; strings render as-is. */
  value: number | string
  format?: NumberFormat
  /** ISO 4217 code, used when `format` is "currency". */
  currency?: string
  /** One value per column of the dot plot. */
  data: number[]
  /** Label per column. The peak's label is shown in the pill, e.g. "Wed". */
  labels?: string[]
  /** Text before the peak's label in the pill, e.g. "Peak" for "Peak: Wed". */
  peakLabel?: string
  /** Absolute change vs the previous period, in the same unit as `value`, e.g. 34002 for +34,002. */
  delta?: number
  /** Context for the delta, e.g. "vs last period". */
  deltaLabel?: string
  /** Format for the delta. Defaults to `format`, except a compact value gets a full number so "+34,002" is not lost to "+34K". */
  deltaFormat?: NumberFormat
  /** Any CSS color for the dots. Defaults to chart-1. */
  color?: string
  /** Number of dots in the tallest column. */
  rows?: number
  /** Formats a column's value in the pill while it is hovered. Defaults to a plain grouped number. */
  valueFormatter?: (value: number) => string
  /** Slot in the top-right corner, e.g. a menu button. */
  action?: React.ReactNode
}

const signedFormatters = new Map<string, Intl.NumberFormat>()

/** "+34,002", "-1.2K", or "+$390" depending on the format. */
function formatSigned(value: number, format: NumberFormat, currency: string) {
  const key = `${format}:${currency}`
  let formatter = signedFormatters.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat("en-US", {
      ...(format === "currency" ? { style: "currency", currency } : {}),
      ...(format === "percent" ? { style: "percent" } : {}),
      ...(format === "compact" ? { notation: "compact" } : {}),
      signDisplay: "exceptZero",
      maximumFractionDigits: format === "number" ? 0 : 1,
    })
    signedFormatters.set(key, formatter)
  }
  return formatter.format(value)
}

/** A metric card with a big value, a dot-plot distribution with its peak called out, and the change vs the previous period. */
function DotPlotCard({
  title,
  value,
  format = "number",
  currency = "USD",
  data,
  labels,
  peakLabel = "Peak",
  delta,
  deltaLabel = "vs last period",
  deltaFormat = format === "compact" ? "number" : format,
  color = "var(--chart-1)",
  rows = 6,
  valueFormatter = (columnValue) => columnValue.toLocaleString("en-US"),
  action,
  className,
  ...props
}: DotPlotCardProps) {
  const [active, setActive] = React.useState<number | null>(null)
  const peak = labels?.[data.indexOf(Math.max(...data))]
  // The pill doubles as the hover readout: it shows the peak by default and the hovered column's value while hovering.
  const pill =
    active !== null ? (
      <>
        {labels?.[active] !== undefined ? `${labels[active]}: ` : null}
        <span className="text-foreground font-medium">{valueFormatter(data[active] ?? 0)}</span>
      </>
    ) : peak !== undefined ? (
      <>
        {peakLabel}: <span className="text-foreground font-medium">{peak}</span>
      </>
    ) : null
  const displayValue =
    typeof value === "number" ? formatNumber(value, { format, currency }) : value

  return (
    <Card data-slot="dot-plot-card" className={cn("gap-4 py-5", className)} {...props}>
      <CardHeader className="px-5">
        <CardTitle className="text-base">{title}</CardTitle>
        {action ? <CardAction>{action}</CardAction> : null}
      </CardHeader>
      <CardContent className="@container px-5">
        {/*
          Narrow: pill, then value and delta side by side, then the plot on its own row.
          From 24rem: value | plot | delta on one row with the pill centered above the plot.
        */}
        <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-4 gap-y-3 @sm:grid-cols-[auto_minmax(0,1fr)_auto]">
          {pill !== null ? (
            <span className="bg-muted text-muted-foreground col-span-2 justify-self-center rounded-full px-3 py-1.5 text-xs whitespace-nowrap @sm:col-span-1 @sm:col-start-2">
              {pill}
            </span>
          ) : null}
          <span className="col-start-1 row-start-2 text-4xl font-semibold tabular-nums tracking-tight">
            {displayValue}
          </span>
          <DotPlot
            data={data}
            labels={labels}
            rows={rows}
            color={color}
            showTooltip={false}
            onActiveIndexChange={setActive}
            className="col-span-2 row-start-3 @sm:col-span-1 @sm:col-start-2 @sm:row-start-2"
          />
          {delta !== undefined ? (
            <div className="col-start-2 row-start-2 flex flex-col items-end @sm:col-start-3">
              <span className="text-muted-foreground text-xs">{deltaLabel}</span>
              <span className="text-xl font-semibold tabular-nums tracking-tight">
                {formatSigned(delta, deltaFormat, currency)}
              </span>
            </div>
          ) : null}
        </div>
      </CardContent>
    </Card>
  )
}

export { DotPlotCard }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

export interface DotPlotProps extends React.ComponentProps<"div"> {
  /** One value per column, in order. */
  data: number[]
  /** Optional label per column, shown in the tooltip and used for the accessible name. */
  labels?: string[]
  /** The value that fills a column. Defaults to the largest value in `data`. */
  max?: number
  /** Number of dots in a full column. */
  rows?: number
  /** Any CSS color. Defaults to chart-1. */
  color?: string
  /**
   * Columns at or above this fraction of `max` are drawn at full strength and the
   * rest are faded, so the peak stands out. Set to 0 to draw every column at full strength.
   */
  emphasis?: number
  /** Opacity of the faded columns. */
  fadedOpacity?: number
  /** Show a tooltip with the column's label and value while it is hovered. */
  showTooltip?: boolean
  /** Formats the value in the tooltip. Defaults to a plain grouped number. */
  valueFormatter?: (value: number) => string
  /** Index of the hovered column, to control it from outside. */
  activeIndex?: number | null
  /** Called when the hovered column changes, with null when the pointer leaves. */
  onActiveIndexChange?: (index: number | null) => void
}

const defaultFormatter = (value: number) => value.toLocaleString("en-US")

/**
 * A distribution drawn as columns of stacked dots, with the peak columns at full strength.
 * Hovering a column lights it up, fades the others, and shows its value.
 */
function DotPlot({
  data,
  labels,
  max,
  rows = 6,
  color = "var(--chart-1)",
  emphasis = 0.5,
  fadedOpacity = 0.35,
  showTooltip = true,
  valueFormatter = defaultFormatter,
  activeIndex,
  onActiveIndexChange,
  className,
  ...props
}: DotPlotProps) {
  const [internal, setInternal] = React.useState<number | null>(null)
  const active = activeIndex === undefined ? internal : activeIndex
  const setActive = (index: number | null) => {
    setInternal(index)
    onActiveIndexChange?.(index)
  }

  const top = max ?? Math.max(0, ...data)
  const peak = data.indexOf(Math.max(...data))
  const peakLabel = labels?.[peak]

  return (
    <div
      data-slot="dot-plot"
      role="img"
      aria-label={
        peakLabel !== undefined
          ? `Distribution across ${data.length} points, peaking at ${peakLabel}`
          : `Distribution across ${data.length} points`
      }
      onPointerLeave={() => setActive(null)}
      className={cn(
        // Dot size and gap are variables so they can be tuned from className, e.g. "[--dot-size:0.75rem]".
        "flex w-full justify-center [--dot-gap:0.25rem] [--dot-size:0.625rem]",
        className
      )}
      {...props}
    >
      {data.map((value, index) => {
        const fraction = Math.min(1, Math.max(0, value / (top || 1)))
        // Any non-zero value shows at least one dot so small values still register.
        const count = fraction === 0 ? 0 : Math.max(1, Math.round(fraction * rows))
        const strong = emphasis <= 0 || fraction >= emphasis
        // While a column is hovered it alone is lit; otherwise the emphasized columns are.
        const lit = active === null ? strong : active === index
        const label = labels?.[index]
        return (
          <div
            key={index}
            data-slot="dot-plot-column"
            data-emphasis={strong}
            data-active={active === index}
            onPointerEnter={() => setActive(index)}
            // Columns stretch to the full height and carry the gap as padding, so the hover target has no dead zones.
            // They share the width equally and cap at the dot size, so dots shrink in narrow cards instead of overflowing.
            className="relative flex min-w-0 flex-1 cursor-default flex-col-reverse justify-start gap-(--dot-gap) px-[calc(var(--dot-gap)/2)] max-w-[calc(var(--dot-size)+var(--dot-gap))]"
          >
            {Array.from({ length: count }, (_, dot) => (
              <span
                key={dot}
                className="aspect-square w-full rounded-full transition-opacity"
                style={{ backgroundColor: color, opacity: lit ? 1 : fadedOpacity }}
              />
            ))}
            {showTooltip && active === index ? (
              <span
                role="tooltip"
                className="bg-popover text-popover-foreground pointer-events-none absolute bottom-full left-1/2 z-10 mb-1.5 flex -translate-x-1/2 items-baseline gap-1.5 rounded-md border px-2 py-1 text-xs whitespace-nowrap shadow-md"
              >
                {label !== undefined ? (
                  <span className="text-muted-foreground">{label}</span>
                ) : null}
                <span className="font-medium tabular-nums">{valueFormatter(value)}</span>
              </span>
            ) : null}
          </div>
        )
      })}
    </div>
  )
}

export { DotPlot }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
